from PIL import Image,ImageDraw
import numpy as np
im=Image.open('/app/target.png').convert('RGB')
m=np.array(Image.open('/app/target.png').convert('L'))<128
def runs(row):
 x=np.where(row)[0]; out=[]
 if not len(x):return out
 s=p=x[0]
 for q in x[1:]:
  if q>p+1:out.append((s,p));s=q
  p=q
 out.append((s,p));return out
p1=[]
for v in range(270,710,4):
 rr=runs(m[v]);
 if rr:p1.append((int(round((rr[0][0]+rr[0][1])/2)),v))
p2=[(484,455)]
for v in range(470,711,5):
 rr=runs(m[v]);
 if rr:p2.append((int(round((rr[-1][0]+rr[-1][1])/2)),v))
p2 += [(780,708),(810,708)]
d=ImageDraw.Draw(im)
d.line(p1,fill=(255,0,0),width=36,joint='curve')
d.line(p2,fill=(0,80,255),width=36,joint='curve')
for p in [p1[0],p1[-1],p2[0],p2[-1]]: d.ellipse((p[0]-4,p[1]-4,p[0]+4,p[1]+4),fill=(255,255,0))
im.save('/app/output/centerline_preview.png')
print('p1',p1[::10],p1[-1],len(p1),'p2',p2[::10],p2[-1],len(p2))
